data:
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&display=swap');

@layer tokens, base, atoms, layout, sections, scenes;

@layer tokens {
:root {
  /* Observed / Adapted Project Design Tokens */
  --background: #F8FAFC;
  --surface: #FFFFFF;
  --ink: #1E293B;
  --muted: #64748B;
  --rule: #E2E8F0;
  --navy: #111D30;
  --red: #ED1D23;
  --orange: #F73B0F;
  --action: #B91C22;
  --pale: #E8EEF4;
  --warm: #F6D9CF;
  --slate: #8A96A8;

  /* 8B Template Variable Mappings */
  --color-1: var(--background);
  --color-2: var(--ink);
  --color-3: var(--muted);
  --color-4: var(--action);
  --color-4-expressive: var(--red);
  --color-5: var(--orange);
  --color-6: var(--warm);
  --color-7: var(--navy);
  --color-8: var(--navy);
  --color-9: var(--slate);
  --color-10: var(--pale);
  --color-11: var(--surface);
  --color-12: var(--rule);

  --font-1: "Montserrat", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-2: "Montserrat", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --radius-1: 24px;
  --radius-2: 999px;
  --radius-3: 12px;
  --shadow-1: 0 1px 0 var(--color-12);
  --space-1: clamp(20px, 5vw, 64px);
  --space-2: clamp(96px, 12vw, 168px);
}
}

@layer base {
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; scroll-behavior: smooth; }
html.lenis, html.lenis body { height: auto; }
.lenis.lenis-smooth [data-lenis-prevent] { overscroll-behavior: contain; }
.lenis.lenis-stopped { overflow: clip; }
.lenis.lenis-smooth iframe { pointer-events: none; }
body {
  margin: 0;
  background: var(--color-1);
  color: var(--color-2);
  font-family: var(--font-2);
  font-size: 17px;
  font-weight: 400;
  line-height: 1.6;
  overflow-x: clip;
}
h1, h2, h3, h4, p, ul, ol, figure, blockquote, dl, dd { margin: 0; }
ul, ol { padding: 0; list-style: none; }
img { display: block; max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--color-4); outline-offset: 4px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.skip { position: fixed; left: 12px; top: -80px; z-index: 100; padding: 12px 18px; background: var(--color-11); border-radius: var(--radius-2); font-weight: 600; }
.skip:focus { top: 12px; }
}

@layer atoms {
.m-text { font-family: var(--font-2); font-size: clamp(16px, 0.25vw + 15px, 18px); font-weight: 400; line-height: 1.6; letter-spacing: 0; }
.m-text-2 { font-family: var(--font-1); font-size: clamp(38px, 6vw, 96px); font-weight: 600; line-height: 0.96; letter-spacing: 0.02em; text-transform: uppercase; }
.m-text-3 { font-family: var(--font-1); font-size: clamp(32px, 4.6vw, 68px); font-weight: 600; line-height: 1.02; letter-spacing: 0.01em; text-transform: uppercase; }
.m-text-4 { font-family: var(--font-2); font-size: 13px; font-weight: 600; line-height: 1.3; letter-spacing: 0.08em; text-transform: uppercase; }
.m-text-5 { font-family: var(--font-2); font-size: clamp(15px, 0.25vw + 14px, 17px); font-weight: 400; line-height: 1.6; color: var(--color-3); }
.m-text-6 { font-family: var(--font-2); font-size: clamp(18px, 0.6vw + 15px, 22px); font-weight: 500; line-height: 1.45; }
.m-text-7 { font-family: var(--font-1); font-size: clamp(22px, 1.6vw + 14px, 32px); font-weight: 600; line-height: 1.1; letter-spacing: 0.01em; text-transform: uppercase; }

.m-btn { position: relative; display: inline-flex; align-items: center; justify-content: center; min-height: 54px; padding: 0 32px; border: 0; border-radius: var(--radius-2); background: var(--color-4); color: var(--color-11); font-family: var(--font-2); font-size: 16px; font-weight: 600; line-height: 1; letter-spacing: 0.01em; white-space: nowrap; overflow: hidden; isolation: isolate; transition: background-color 0.2s; }
.m-btn::before { content: ""; position: absolute; inset: -2px -30%; z-index: -1; background: var(--color-7); transform: translateX(-105%) skewX(-24deg); transition: transform 0.55s cubic-bezier(0.65, 0, 0.2, 1); }
.m-btn__label { position: relative; }
@media (hover: hover) { .m-btn:hover::before { transform: translateX(0) skewX(-24deg); } }
.m-btn-2 { position: relative; display: inline-flex; align-items: center; justify-content: center; min-height: 52px; padding: 0 28px; border: 1.5px solid currentColor; border-radius: var(--radius-2); background: transparent; color: var(--color-11); font-family: var(--font-2); font-size: 16px; font-weight: 600; line-height: 1; letter-spacing: 0.01em; white-space: nowrap; overflow: hidden; isolation: isolate; transition: color 0.4s; }
.m-btn-2::before { content: ""; position: absolute; inset: -2px -30%; z-index: -1; background: var(--color-11); transform: translateX(-105%) skewX(-24deg); transition: transform 0.55s cubic-bezier(0.65, 0, 0.2, 1); }
.m-btn-2__label { position: relative; }
@media (hover: hover) { .m-btn-2:hover { color: var(--color-2); } .m-btn-2:hover::before { transform: translateX(0) skewX(-24deg); } }
.m-btn-2:focus-visible { outline-color: var(--color-11); }

.m-link { position: relative; display: inline-block; color: inherit; font-weight: 600; }
.m-link::after { content: ""; position: absolute; left: 0; right: 0; bottom: -3px; height: 2px; background: currentColor; transform-origin: 0 50%; transform: rotate(-6deg) scaleX(0); transition: transform 0.4s cubic-bezier(0.65, 0, 0.2, 1); }
@media (hover: hover) { .m-link:hover::after { transform: rotate(0deg) scaleX(1); } }

.m-circle { display: inline-flex; align-items: center; gap: 20px; color: var(--color-4); font-family: var(--font-2); font-size: 16px; font-weight: 600; line-height: 1.2; letter-spacing: 0.04em; text-transform: uppercase; }
.m-circle__disc { position: relative; flex: none; display: grid; place-items: center; width: 104px; height: 104px; border-radius: var(--radius-2); }
.m-circle__disc::before { content: ""; position: absolute; inset: 8px; border-radius: inherit; background: var(--color-4); transition: transform 0.5s cubic-bezier(0.65, 0, 0.2, 1); }
.m-circle__ring { position: absolute; inset: 0; width: 100%; height: 100%; fill: none; stroke: var(--color-4); stroke-width: 1.5; stroke-dasharray: 210 92; transition: stroke-dasharray 0.6s cubic-bezier(0.65, 0, 0.2, 1); }
.m-circle__arrow { position: relative; width: 36px; height: 16px; fill: none; stroke: var(--color-11); stroke-width: 2; transition: transform 0.5s cubic-bezier(0.65, 0, 0.2, 1); }
@media (hover: hover) {
  .m-circle:hover .m-circle__ring { stroke-dasharray: 302 0; }
  .m-circle:hover .m-circle__arrow { transform: rotate(-35deg); }
  .m-circle:hover .m-circle__disc::before { transform: scale(0.92) rotate(-8deg); }
}

.m-glyph { --glyph-size: 36px; position: relative; display: inline-block; flex: none; width: var(--glyph-size); height: var(--glyph-size); }
.m-glyph i { position: absolute; width: 33.4%; height: 33.4%; border-radius: 2px; }
.m-glyph i:nth-child(1) { left: 0; top: 0; background: var(--color-7); }
.m-glyph i:nth-child(2) { left: 66.6%; top: 0; background: var(--color-4-expressive); }
.m-glyph i:nth-child(3) { left: 33.3%; top: 33.3%; background: var(--color-6); }
.m-glyph i:nth-child(4) { left: 66.6%; top: 33.3%; background: var(--color-5); }
.m-glyph i:nth-child(5) { left: 33.3%; top: 66.6%; background: var(--color-7); }

.m-glyph-2 { --glyph-size: 36px; position: relative; display: inline-block; flex: none; width: var(--glyph-size); height: var(--glyph-size); }
.m-glyph-2 i { position: absolute; width: 33.4%; height: 33.4%; border-radius: 2px; }
.m-glyph-2 i:nth-child(1) { left: 0; top: 0; background: var(--color-10); }
.m-glyph-2 i:nth-child(2) { left: 66.6%; top: 0; background: var(--color-6); }
.m-glyph-2 i:nth-child(3) { left: 33.3%; top: 33.3%; background: var(--color-5); }
.m-glyph-2 i:nth-child(4) { left: 66.6%; top: 33.3%; background: var(--color-11); }
.m-glyph-2 i:nth-child(5) { left: 33.3%; top: 66.6%; background: var(--color-6); }

.m-surface { border-radius: var(--radius-1); background: var(--color-11); color: var(--color-2); overflow: hidden; border: 1px solid var(--color-12); }
.m-field { display: grid; gap: 8px; }
.m-field__label { font-family: var(--font-2); font-size: 14px; font-weight: 600; line-height: 1.3; color: var(--color-2); }
.m-field__control { width: 100%; min-height: 50px; padding: 12px 16px; border: 1.5px solid var(--color-12); border-radius: var(--radius-3); background: var(--color-1); color: var(--color-2); font-family: var(--font-2); font-size: 15px; line-height: 1.4; transition: border-color 0.3s; }
.m-field__control:focus-visible { outline: 2px solid var(--color-4); outline-offset: 2px; border-color: var(--color-2); }
textarea.m-field__control { min-height: 100px; resize: vertical; }
select.m-field__control { appearance: none; padding-right: 44px; background-image: linear-gradient(45deg, transparent 50%, var(--color-2) 50%), linear-gradient(135deg, var(--color-2) 50%, transparent 50%); background-position: calc(100% - 22px) 52%, calc(100% - 16px) 52%; background-size: 6px 6px; background-repeat: no-repeat; }
@media (hover: hover) { .m-field__control:hover { border-color: var(--color-9); } }

.m-badge { display: inline-flex; align-items: center; min-height: 30px; padding: 0 12px; border: 1px solid currentColor; border-radius: var(--radius-2); font-family: var(--font-2); font-size: 12px; font-weight: 600; line-height: 1; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }
.m-badge--notice { background: var(--color-10); color: var(--color-7); border-color: transparent; }
.m-badge--accent { background: var(--color-6); color: var(--color-7); border-color: transparent; }
}

@layer layout {
.planes { position: relative; container-type: size; overflow: hidden; }
.plane { position: absolute; --k: 0; transform: translate(calc((1 - var(--k)) * var(--tx, 0) * 1cqw), calc((1 - var(--k)) * var(--ty, 0) * 1cqh)) rotate(calc((1 - var(--k)) * var(--r, 0) * 1deg)) scale(calc(1 + (1 - var(--k)) * (var(--s, 1) - 1))); }
.plane__fill { position: absolute; inset: 0; }
.wrap { width: 100%; max-width: 1440px; margin-inline: auto; padding-inline: var(--space-1); }

/* Notice bar at very top */
.notice-bar { background: var(--color-7); color: var(--color-11); padding: 8px var(--space-1); font-size: 13px; font-weight: 500; text-align: center; display: flex; align-items: center; justify-content: center; gap: 8px; z-index: 50; position: relative; }
.notice-bar span { opacity: 0.95; }
.notice-bar a { text-decoration: underline; text-underline-offset: 3px; font-weight: 600; }

/* Disclaimer callout box */
.disclaimer-box { background: var(--color-10); border-left: 4px solid var(--color-4); border-radius: 8px; padding: 14px 18px; margin: 24px 0; font-size: 14px; line-height: 1.5; color: var(--color-7); }
.disclaimer-box strong { font-weight: 600; display: block; margin-bottom: 4px; }
}

@layer sections {
/* Navigation */
#nav { position: sticky; top: 0; z-index: 40; transition: transform 0.45s cubic-bezier(0.65, 0, 0.2, 1), background-color 0.3s; background: rgba(248, 250, 252, 0.95); backdrop-filter: blur(10px); border-bottom: 1px solid var(--color-12); }
#nav .nav__bar { display: flex; align-items: center; gap: 24px; height: 84px; }
#nav.is-solid { background: var(--color-1); box-shadow: var(--shadow-1); }
#nav.is-hidden { transform: translateY(-100%); }
#nav .nav__logo { display: inline-flex; align-items: center; gap: 12px; margin-right: auto; text-decoration: none; }
#nav .nav__brand-box { display: flex; flex-direction: column; }
#nav .nav__word { font-family: var(--font-1); font-size: 20px; font-weight: 600; line-height: 1.1; letter-spacing: 0.01em; color: var(--color-2); }
#nav .nav__subline { font-size: 11px; font-weight: 600; color: var(--color-4); letter-spacing: 0.05em; text-transform: uppercase; }
#nav .nav__links { display: flex; gap: 28px; align-items: center; }
#nav .nav__link { font-size: 15px; font-weight: 500; color: var(--color-3); transition: color 0.2s; }
#nav .nav__link:hover, #nav .nav__link[aria-current="true"] { color: var(--color-2); font-weight: 600; }
#nav .nav__cta { margin-left: 16px; min-height: 44px; padding: 0 24px; font-size: 14px; }
#nav .nav__menu { display: none; min-height: 40px; padding: 0 16px; border: 1.5px solid var(--color-2); border-radius: var(--radius-2); background: transparent; font-size: 14px; font-weight: 600; }

#nav .menu { position: fixed; inset: 0; z-index: 60; display: flex; flex-direction: column; padding: 24px var(--space-1) 40px; background: var(--color-7); color: var(--color-11); overflow-y: auto; }
#nav .menu[hidden] { display: none; }
#nav .menu .menu__top { display: flex; justify-content: space-between; align-items: center; height: 48px; }
#nav .menu .menu__close { min-height: 40px; padding: 0 18px; border: 1.5px solid var(--color-11); border-radius: var(--radius-2); background: transparent; color: var(--color-11); font-size: 14px; font-weight: 600; }
#nav .menu .menu__close:focus-visible, #nav .menu a:focus-visible { outline-color: var(--color-11); }
#nav .menu .menu__links { display: grid; gap: 12px; margin-top: auto; padding-top: 40px; }
#nav .menu .menu__links a { font-family: var(--font-1); font-size: clamp(28px, 8vw, 48px); font-weight: 600; text-transform: uppercase; line-height: 1.1; }
#nav .menu .menu__subline { font-size: 14px; opacity: 0.8; margin-top: 16px; }

/* Hero Section */
#hero { position: relative; padding-bottom: 40px; }
#hero .hero__top { padding-top: clamp(24px, 4vw, 48px); }
#hero .hero__eyebrow { display: inline-flex; align-items: center; gap: 10px; margin-bottom: 16px; font-size: 13px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--color-4); }
#hero .hero__title { max-width: 1200px; color: var(--color-2); }
#hero .hero__intro { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 28px; margin-top: 24px; max-width: 1200px; }
#hero .hero__intro-text { max-width: 680px; }
#hero .hero__stage { position: relative; margin-top: 36px; }
#hero .hero__panel { position: relative; height: clamp(480px, 70vh, 700px); border-radius: var(--radius-1); overflow: hidden; background: var(--color-11); border: 1px solid var(--color-12); }
#hero .hero__frame { position: absolute; inset: 0; }

#hero .plane--orange { left: 0; top: 0; width: 44%; height: 84%; --tx: -24; --ty: 10; --r: -16; --s: 1.2; }
#hero .plane--orange .plane__fill { background: var(--color-5); }
#hero .plane--plum { left: 44%; top: 0; width: 56%; height: 84%; --tx: 20; --ty: -14; --r: 18; --s: 1.35; }
#hero .plane--plum .plane__fill { background: var(--color-7); }
#hero .plane--ice { left: 0; top: 84%; width: 100%; height: 16%; --tx: -20; --ty: 20; --r: -12; --s: 1.1; }
#hero .plane--ice .plane__fill { background: var(--color-10); border-top: 1px solid var(--color-12); }
#hero .plane--deep { left: calc(44% - 6cqh); top: calc(84% - 6cqh); width: 12cqh; height: 12cqh; border-radius: 50%; --tx: 30; --ty: 20; --r: 40; --s: 2.2; }
#hero .plane--deep .plane__fill { background: var(--color-8); }
#hero .plane--chip { left: 32%; top: 12%; width: 5cqh; height: 5cqh; border-radius: 4px; --tx: -30; --ty: -24; --r: 25; --s: 1.5; }
#hero .plane--chip .plane__fill { background: var(--color-4-expressive); }
#hero .plane--photo { left: 6%; top: 12%; width: 34%; height: 64%; margin: 0; border-radius: var(--radius-1); overflow: hidden; --tx: 18; --ty: -10; --r: -8; --s: 0.85; box-shadow: 0 12px 32px rgba(17, 29, 48, 0.15); }
#hero .plane--photo img { width: 100%; height: 100%; object-fit: cover; }
#hero .hero__tour { left: calc(42% - 52px); top: calc(44% - 52px); z-index: 4; display: grid; place-items: center; width: 104px; height: 104px; border-radius: var(--radius-2); background: var(--color-11); color: var(--color-7); font-family: var(--font-2); font-size: 13px; font-weight: 600; line-height: 1.2; letter-spacing: 0.04em; text-align: center; text-transform: uppercase; box-shadow: 0 8px 24px rgba(0,0,0,0.12); --tx: -22; --ty: 12; --r: 14; --s: 1; text-decoration: none; transition: transform 0.3s; }
#hero .hero__tour:hover { transform: scale(1.06); }
#hero .hero__say { position: absolute; left: 48%; right: var(--space-1); top: 12%; z-index: 3; color: var(--color-11); }
#hero .hero__say .m-text-3 { color: var(--color-11); }
#hero .hero__say-text { margin-top: 18px; max-width: 520px; color: var(--color-10); font-size: clamp(16px, 1.2vw, 19px); line-height: 1.5; }
#hero .hero__cta { margin-top: 28px; }

/* Bottom text-only pathway ribbon (no fake partner marks) */
#hero .hero__ship { position: absolute; left: var(--space-1); right: var(--space-1); bottom: 0; height: 16%; z-index: 3; display: flex; align-items: center; justify-content: space-between; gap: 24px; color: var(--color-7); }
#hero .hero__ship-label { font-size: 13px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--color-3); flex: none; }
#hero .hero__ship ul { display: flex; gap: 32px; align-items: center; flex-wrap: wrap; }
#hero .ship { display: inline-flex; align-items: center; gap: 8px; font-weight: 600; font-size: 15px; color: var(--color-7); }

/* Career / Pathways Section (#carry) */
#carry { padding: var(--space-2) 0; }
#carry .carry__head { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-1); align-items: end; margin-bottom: 48px; }
#carry .carry__title { display: flex; align-items: center; gap: 16px; }
#carry .diff { border-top: 1.5px solid var(--color-12); }
#carry .diff__row { display: grid; grid-template-columns: 1.2fr 1.2fr 1fr auto; align-items: center; gap: 24px; padding: 32px 0; border-bottom: 1.5px solid var(--color-12); text-decoration: none; color: inherit; transition: background-color 0.2s; }
#carry .diff__row:hover { background: rgba(232, 238, 244, 0.4); }
#carry .diff__old { color: var(--color-3); }
#carry .diff__new { font-weight: 600; color: var(--color-2); }
#carry .diff__kept { color: var(--color-3); }
#carry .diff__link { font-weight: 600; color: var(--color-4); white-space: nowrap; }

/* Curriculum / 5 Emphases Horizontal Section (#course) */
#course { padding: var(--space-2) 0; background: var(--color-7); color: var(--color-11); }
#course .course__head { margin-bottom: 48px; }
#course .course__head .m-text-3 { color: var(--color-11); }
#course .course__head .course__lead { color: var(--color-10); margin-top: 16px; max-width: 720px; }
#course .course__stage { position: relative; overflow: hidden; }
#course .course__track { display: flex; gap: 32px; width: max-content; padding-bottom: 32px; }
#course .mod { position: relative; width: clamp(320px, 40vw, 480px); background: #182840; border-radius: var(--radius-1); overflow: hidden; border: 1px solid rgba(255,255,255,0.1); display: flex; flex-direction: column; }
#course .mod__planes { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
#course .mod__plane { position: absolute; width: 120%; height: 120%; transform: rotate(-8deg); background: rgba(237, 29, 35, 0.05); }
#course .mod__plane--2 { background: rgba(247, 59, 15, 0.05); transform: rotate(12deg); }
#course .mod__text { position: relative; z-index: 2; padding: 32px; flex: 1; }
#course .mod__text .m-text-7 { margin: 16px 0 12px; color: var(--color-11); }
#course .mod__text p { color: var(--color-10); }
#course .mod__build { margin-top: 24px; padding-top: 16px; border-top: 1px solid rgba(255,255,255,0.15); }
#course .mod__photo { position: relative; z-index: 2; height: 220px; overflow: hidden; margin: 0; }
#course .mod__photo img { width: 100%; height: 100%; object-fit: cover; }
#course .course__weeks { margin-top: 36px; }
#course .weeks { display: flex; gap: 8px; justify-content: space-between; }
#course .weeks li { flex: 1; height: 6px; background: rgba(255,255,255,0.2); border-radius: 3px; position: relative; overflow: hidden; }
#course .weeks li::after { content: ""; position: absolute; inset: 0; background: var(--color-4-expressive); transform: scaleX(var(--fill, 0)); transform-origin: left; transition: transform 0.2s; }
#course .weeks__ends { display: flex; justify-content: space-between; margin-top: 12px; color: var(--color-10); font-size: 13px; }

/* Schedule / Formats Section (#week) */
#week { padding: var(--space-2) 0; }
#week .week__head { margin-bottom: 56px; max-width: 840px; }
#week .slots { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
#week .slot { background: var(--color-11); border-radius: var(--radius-1); overflow: hidden; border: 1px solid var(--color-12); display: flex; flex-direction: column; }
#week .slot__photo { height: 240px; overflow: hidden; margin: 0; }
#week .slot__photo img { width: 100%; height: 100%; object-fit: cover; }
#week .slot__what { padding: 28px; flex: 1; }
#week .slot__what h3 { margin-bottom: 8px; }
#week .slot__what p { margin-top: 8px; }

/* Mentors / Stakeholder Alignment (#mentors) */
#mentors { padding: var(--space-2) 0; background: var(--color-10); }
#mentors .mentors__head { margin-bottom: 56px; max-width: 800px; }
#mentors .mentors__grid { display: grid; grid-template-columns: 1fr 1.2fr; gap: var(--space-1); align-items: start; }
#mentors .viewer { position: sticky; top: 120px; height: 460px; border-radius: var(--radius-1); overflow: hidden; box-shadow: 0 16px 36px rgba(17, 29, 48, 0.1); }
