/**
 * Motion Controller for TAPMI M3 Student Website
 * Scoped GSAP 3.13, ScrollTrigger & Lenis 1.3.27
 * With full prefers-reduced-motion accessibility & no-JS / CDN fallback
 */

(() => {
  'use strict';

  // Navigation Mobile Menu & Header Behavior
  const header = document.getElementById('nav');
  const menu = document.getElementById('menu');

  if (header && menu) {
    const openButton = header.querySelector('.nav__menu');
    const closeButton = menu.querySelector('.menu__close');
    let lastY = window.scrollY, travel = 0;

    const onScroll = () => {
      const y = window.scrollY;
      const delta = y - lastY;
      lastY = y;
      header.classList.toggle('is-solid', y > 24);
      if (Math.sign(delta) !== Math.sign(travel)) travel = 0;
      travel += delta;
      if (y < 120 || travel < -6) {
        header.classList.remove('is-hidden');
      } else if (travel > 6) {
        header.classList.add('is-hidden');
      }
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();

    header.addEventListener('focusin', () => header.classList.remove('is-hidden'));

    const setMenu = open => {
      menu.hidden = !open;
      if (openButton) openButton.setAttribute('aria-expanded', String(open));
      if (open) {
        window.lenis?.stop();
        if (closeButton) closeButton.focus();
      } else {
        window.lenis?.start();
        if (openButton) openButton.focus();
      }
    };

    if (openButton) openButton.addEventListener('click', () => setMenu(true));
    if (closeButton) closeButton.addEventListener('click', () => setMenu(false));
    menu.addEventListener('keydown', event => { if (event.key === 'Escape') setMenu(false); });
    menu.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => setMenu(false));
    });
  }

  // Check prefers-reduced-motion
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (prefersReducedMotion) {
    // Graceful exit: no smooth scrolling, no pinning, elements remain in natural document flow
    return;
  }

  // Check if GSAP & Lenis are available
  if (typeof window.gsap === 'undefined' || typeof window.ScrollTrigger === 'undefined') {
    // CDN failure or offline: keep plain HTML/CSS fallback
    return;
  }

  window.gsap.registerPlugin(window.ScrollTrigger);

  // Smooth scroll with Lenis (only when motion is preferred)
  if (typeof window.Lenis !== 'undefined') {
    const lenis = window.lenis = new window.Lenis({
      lerp: 0.09,
      wheelMultiplier: 0.9
    });
    lenis.on('scroll', window.ScrollTrigger.update);
    window.gsap.ticker.add(time => lenis.raf(time * 1000));
    window.gsap.ticker.lagSmoothing(0);
  }

  // Horizontal Curriculum track pinning (#course)
  const courseSection = document.getElementById('course');
  if (courseSection && window.innerWidth >= 900) {
    const stage = courseSection.querySelector('.course__stage');
    const track = courseSection.querySelector('.course__track');
    const squares = [...courseSection.querySelectorAll('.weeks > li')];

    if (stage && track) {
      const distance = () => Math.max(0, track.offsetWidth - stage.clientWidth);
      const timeline = window.gsap.timeline({
        defaults: { ease: 'none' },
        scrollTrigger: {
          id: 'course-horizontal',
          trigger: stage,
          start: 'top 80px',
          end: () => `+=${Math.round(distance() * 1.15)}`,
          pin: true,
          scrub: 0.6,
          invalidateOnRefresh: true
        }
      });
      timeline.fromTo(track, { x: 0 }, { x: () => -distance(), duration: 1 }, 0);
      squares.forEach((sq, i) => {
        timeline.fromTo(sq, { '--fill': 0 }, { '--fill': 1, duration: 0.05, ease: 'power2.out' }, (i / squares.length) * 0.95);
      });
    }
  }

  // Sticky Programme Stack (#projects)
  const projectsSection = document.getElementById('projects');
  if (projectsSection) {
    const cards = [...projectsSection.querySelectorAll('.proj')];
    cards.forEach((card, i) => {
      const next = cards[i + 1];
      if (!next) return;
      window.gsap.fromTo(card,
        { scale: 1, rotation: 0, filter: 'brightness(1)' },
        {
          scale: 0.9,
          rotation: -2,
          filter: 'brightness(0.7)',
          ease: 'none',
          scrollTrigger: {
            id: `proj-stack-${i + 1}`,
            trigger: next,
            start: 'top bottom',
            end: 'top 120px',
            scrub: true,
            invalidateOnRefresh: true
          }
        }
      );
    });
  }

  // Mentors viewer image swap (#mentors)
  const mentorsSection = document.getElementById('mentors');
  if (mentorsSection) {
    const shots = [...mentorsSection.querySelectorAll('.viewer__shot')];
    mentorsSection.querySelectorAll('.mentor').forEach((person, i) => {
      const shot = shots[i];
      if (!i || !shot) return;
      window.gsap.timeline({
        scrollTrigger: {
          id: `mentor-shot-${i + 1}`,
          trigger: person,
          start: 'top 75%',
          end: 'top 45%',
          scrub: 0.4,
          invalidateOnRefresh: true
        }
      })
      .fromTo(shot, { clipPath: 'polygon(0% 100%, 100% 100%, 100% 100%, 0% 100%)' }, { clipPath: 'polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)', ease: 'power2.inOut' }, 0)
      .fromTo(shot.querySelector('img'), { scale: 1.15 }, { scale: 1, ease: 'power2.out' }, 0);
    });
  }

  // Dealt fee cards (#fees)
  const feesSection = document.getElementById('fees');
  if (feesSection && window.innerWidth >= 900) {
    const plans = [...feesSection.querySelectorAll('.plan')];
    const grid = feesSection.querySelector('.plans');
    if (plans.length && grid) {
      const turns = [-4, 2, 6];
      plans.forEach((plan, i) => {
        window.gsap.fromTo(plan, {
          y: 40 + i * 15,
          rotation: turns[i % turns.length]
        }, {
          y: 0,
          rotation: 0,
          ease: 'power2.out',
          scrollTrigger: {
            id: `fee-plan-${i + 1}`,
            trigger: grid,
            start: 'top 85%',
            end: 'top 40%',
            scrub: 0.5,
            invalidateOnRefresh: true
          }
        });
      });
    }
  }

  // Contact planes entrance (#contact)
  const contactSection = document.getElementById('contact');
  if (contactSection) {
    const planes = contactSection.querySelectorAll('.contact__planes > .plane');
    if (planes.length) {
      window.gsap.fromTo(planes, { '--k': 0 }, {
        '--k': 1,
        stagger: 0.1,
        ease: 'power2.inOut',
        scrollTrigger: {
          id: 'contact-planes',
          trigger: contactSection,
          start: 'top 90%',
          end: 'center 60%',
          scrub: 0.6
        }
      });
    }
  }

  // Refresh triggers on resize
  let resizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      window.ScrollTrigger.refresh();
    }, 250);
  });
})();

/**
 * Client-Side Enquiry Handling & Validation
 * Group 4: Academic Prototype Website
 */

document.addEventListener('DOMContentLoaded', () => {
  const forms = document.querySelectorAll('.contact__form, .enquiry-form');
  if (!forms.length) return;

  // Read scenario from URL search params if present
  const urlParams = new URLSearchParams(window.location.search);
  const requestedScenario = urlParams.get('scenario');

  forms.forEach(form => {
    const scenarioSelect = form.querySelector('[name="scenario_id"]');
    const statusBox = form.querySelector('.form-status');
    const demoNotice = form.querySelector('.demo-mode-notice');
    const submitBtn = form.querySelector('button[type="submit"]');
    const submitLabel = submitBtn ? submitBtn.querySelector('.m-btn__label, span') : null;
    const testFillBtn = form.querySelector('.btn-test-fill');

    if (scenarioSelect && requestedScenario) {
      if (['emba_b2b', 'mdp_b2b', 'emba_b2c', 'cert_b2b', 'cert_b2c'].includes(requestedScenario)) {
        scenarioSelect.value = requestedScenario;
      }
    }

    // Toggle B2B vs B2C conditional fields
    function updateFieldVisibility() {
      const currentVal = scenarioSelect ? scenarioSelect.value : (form.dataset.scenario || 'emba_b2b');
      const isB2B = currentVal.includes('b2b');
      const b2bFields = form.querySelectorAll('.field-b2b');
      const b2cFields = form.querySelectorAll('.field-b2c');

      b2bFields.forEach(el => el.style.display = isB2B ? 'grid' : 'none');
      b2cFields.forEach(el => el.style.display = isB2B ? 'none' : 'grid');

      const emailLabel = form.querySelector('.label-email');
      if (emailLabel) {
        emailLabel.textContent = isB2B ? 'Work email' : 'Email address';
      }
    }

    if (scenarioSelect) {
      scenarioSelect.addEventListener('change', updateFieldVisibility);
      updateFieldVisibility();
    }

    // Check system connection status via GET /api/enquiry
    fetch('/api/enquiry')
      .then(r => r.json())
      .then(data => {
        const isConnected = data.connected === true;
        if (demoNotice) {
          demoNotice.textContent = isConnected 
            ? 'Connected to enquiry system' 
            : 'Demo mode: not connected to the CRM';
          demoNotice.className = isConnected 
            ? 'demo-mode-notice is-connected' 
            : 'demo-mode-notice is-demo';
        }
        if (submitLabel) {
          submitLabel.textContent = isConnected ? 'Send project enquiry' : 'Test enquiry flow';
        }
      })
      .catch(() => {
        if (demoNotice) {
          demoNotice.textContent = 'Demo mode: not connected to the CRM';
          demoNotice.className = 'demo-mode-notice is-demo';
        }
        if (submitLabel) {
          submitLabel.textContent = 'Test enquiry flow';
        }
      });

    // Quick fill with synthetic demo fixture
    if (testFillBtn) {
      testFillBtn.addEventListener('click', (e) => {
        e.preventDefault();
        const currentScenario = scenarioSelect ? scenarioSelect.value : (form.dataset.scenario || 'emba_b2b');
        let fixture = null;
        if (window.CONFIG && window.CONFIG.fixtures) {
          fixture = window.CONFIG.fixtures.find(f => f.scenario_id === currentScenario) || window.CONFIG.fixtures[0];
        } else {
          fixture = {
            name: "Demo Professional",
            email: "demo.professional@example.com",
            organisation: "Technology Services Ltd",
            job_role: "Lead Engineer",
            participant_count: "1",
            capability_need: "Strengthen leadership and strategic decision making."
          };
        }

        const nameInput = form.querySelector('[name="name"]');
        const emailInput = form.querySelector('[name="email"]');
        const orgInput = form.querySelector('[name="organisation"]');
        const roleInput = form.querySelector('[name="job_role"]');
        const countInput = form.querySelector('[name="participant_count"]');
        const needInput = form.querySelector('[name="capability_need"]');
        const consentCheckbox = form.querySelector('[name="consent"]');

        if (nameInput) nameInput.value = fixture.name;
        if (emailInput) emailInput.value = fixture.email;
        if (orgInput) orgInput.value = fixture.organisation || '';
        if (roleInput) roleInput.value = fixture.job_role || '';
        if (countInput) countInput.value = fixture.participant_count || '1';
        if (needInput) needInput.value = fixture.capability_need || '';
        if (consentCheckbox) consentCheckbox.checked = true;

        if (statusBox) {
          statusBox.hidden = false;
          statusBox.className = 'form-status is-info';
          statusBox.textContent = `Loaded synthetic demo fixture for ${fixture.name} (${currentScenario}).`;
        }
      });
    }

    // Submit handler
    form.addEventListener('submit', async (e) => {
      e.preventDefault();

      if (!form.reportValidity()) return;

      const consentCheck = form.querySelector('[name="consent"]');
      if (!consentCheck || !consentCheck.checked) {
        if (statusBox) {
          statusBox.hidden = false;
          statusBox.className = 'form-status is-error';
          statusBox.textContent = 'Please confirm acknowledgement of the student project disclaimer to proceed.';
        }
        return;
      }

      const formData = new FormData(form);
      const payload = {};
      formData.forEach((val, key) => {
        payload[key] = val;
      });

      payload.consent = true;
      payload.is_test = payload.is_test === 'true' || (payload.email && payload.email.endsWith('@example.com'));
      payload.source_page = window.location.pathname;

      // Capture UTM params from page URL
      ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term'].forEach(p => {
        if (urlParams.get(p)) payload[p] = urlParams.get(p);
      });

      if (submitBtn) submitBtn.disabled = true;
      if (statusBox) {
        statusBox.hidden = false;
        statusBox.className = 'form-status is-pending';
        statusBox.textContent = 'Processing project enquiry...';
      }

      try {
        const res = await fetch('/api/enquiry', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });

        const data = await res.json();

        if (res.ok && data.success) {
          statusBox.className = 'form-status is-success';
          if (data.mode === 'demo') {
            statusBox.innerHTML = `
              <strong>Demo recorded in this browser. Nothing was sent to the CRM.</strong><br>
              <small>Request ID: <code>${data.request_id}</code> · Academic student prototype mode.</small>
            `;
          } else {
            statusBox.innerHTML = `
              <strong>Your project enquiry has been received by the enquiry system.</strong><br>
              <small>Request ID: <code>${data.request_id}</code> · This is not an official TAPMI application.</small>
            `;
          }
          // Reset form fields safely
          form.reset();
        } else {
          statusBox.className = 'form-status is-error';
          statusBox.textContent = data.message || 'We could not confirm receipt. Your details are still in this form. Please try again.';
        }
      } catch (err) {
        statusBox.className = 'form-status is-error';
        statusBox.textContent = 'We could not confirm receipt. Your details are still in this form. Please try again.';
      } finally {
        if (submitBtn) submitBtn.disabled = false;
      }
    });
  });
});

/**
 * /api/enquiry - Serverless API Route for TAPMI Student Project Enquiries
 * Handles validation, formula-injection protection, rate limiting, and forwarding
 * to Google Apps Script / Sheet receiver when configured.
 * 
 * Group 4: Ayush (Website), Benjamin (CRM), Anshita (Strategy & Integration)
 */

const crypto = require('crypto');

// Allowed scenario IDs
const VALID_SCENARIOS = ['emba_b2b', 'mdp_b2b', 'emba_b2c', 'cert_b2b', 'cert_b2c'];

// Formula injection protection: escape characters that trigger spreadsheet formulas
function sanitizeFormula(str) {
  if (typeof str !== 'string') return '';
  const trimmed = str.trim();
  if (/^[=+\-@\t\r]/.test(trimmed)) {
    return "'" + trimmed;
  }
  return trimmed;
}

// Basic email validation regex
function isValidEmail(email) {
  if (typeof email !== 'string') return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
}

module.exports = async function handler(req, res) {
  // CORS & Security Headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  // GET: Health / Status check for frontend demo-mode detection
  if (req.method === 'GET') {
    const isConnected = !!(process.env.APPS_SCRIPT_URL && process.env.ENQUIRY_SECRET);
    return res.status(200).json({
      status: 'ok',
      service: 'tapmi-m3-student-enquiry-api',
      mode: isConnected ? 'connected' : 'demo',
      connected: isConnected,
      connectedMessage: isConnected 
        ? 'Connected to team enquiry system' 
        : 'Demo mode: not connected to the CRM',
      disclaimer: 'Student project, not an official TAPMI offering'
    });
  }

  if (req.method !== 'POST') {
    return res.status(405).json({
      error: 'Method Not Allowed',
      message: 'Only POST and GET requests are supported.'
    });
  }

  try {
    const body = typeof req.body === 'string' ? JSON.parse(req.body) : (req.body || {});

    // Required fields validation
    const scenario_id = (body.scenario_id || '').trim();
    if (!scenario_id || !VALID_SCENARIOS.includes(scenario_id)) {
      return res.status(400).json({
        error: 'Invalid scenario_id',
        message: 'A valid programme scenario must be selected.'
      });
    }

    const name = (body.name || '').trim();
    if (!name || name.length < 2 || name.length > 100) {
      return res.status(400).json({
        error: 'Invalid name',
        message: 'Name is required (2–100 characters).'
      });
    }

    const email = (body.email || '').trim();
    if (!email || !isValidEmail(email) || email.length > 120) {
      return res.status(400).json({
        error: 'Invalid email',
        message: 'A valid email address is required.'
      });
    }

    const consent = body.consent === true || body.consent === 'true';
    if (!consent) {
      return res.status(400).json({
        error: 'Consent required',
        message: 'You must acknowledge the student project disclaimer before submitting.'
      });
    }

    // Generate durable request ID
    const request_id = 'req_' + Date.now().toString(36) + '_' + crypto.randomBytes(4).toString('hex');
    const created_at = new Date().toISOString();

    // Map buyer type
    const isB2B = scenario_id.includes('b2b');
    const buyer_type = isB2B ? 'B2B_Organisation' : 'B2C_Individual';

    // Sanitize all incoming fields
    const payload = {
      request_id,
      created_at,
      scenario_id,
      buyer_type,
      name: sanitizeFormula(name),
      email: sanitizeFormula(email),
      phone_optional: sanitizeFormula((body.phone_optional || body.phone || '').slice(0, 30)),
      preferred_contact: body.preferred_contact === 'phone' ? 'phone' : 'email',
      organisation: sanitizeFormula((body.organisation || '').slice(0, 150)),
      job_role: sanitizeFormula((body.job_role || '').slice(0, 100)),
      participant_count: sanitizeFormula(String(body.participant_count || '').slice(0, 20)),
      capability_need: sanitizeFormula((body.capability_need || body.message || '').slice(0, 1000)),
      timeframe: sanitizeFormula((body.timeframe || 'Exploring').slice(0, 50)),
      budget_band: sanitizeFormula((body.budget_band || 'Prefer to discuss').slice(0, 50)),
      message: sanitizeFormula((body.message || '').slice(0, 1000)),
      consent: true,
      consent_version: 'v1.0-student-prototype',
      is_test: body.is_test === true || body.is_test === 'true' || email.endsWith('@example.com'),
      source_page: sanitizeFormula((body.source_page || '/').slice(0, 100)),
      utm_source: sanitizeFormula((body.utm_source || '').slice(0, 50)),
      utm_medium: sanitizeFormula((body.utm_medium || '').slice(0, 50)),
      utm_campaign: sanitizeFormula((body.utm_campaign || '').slice(0, 50)),
      utm_content: sanitizeFormula((body.utm_content || '').slice(0, 50)),
      utm_term: sanitizeFormula((body.utm_term || '').slice(0, 50))
    };

    // Check upstream integration
    const appsScriptUrl = process.env.APPS_SCRIPT_URL;
    const enquirySecret = process.env.ENQUIRY_SECRET;

    if (!appsScriptUrl || !enquirySecret) {
      // Unconfigured upstream -> DEMO MODE
      // Safe feedback without silent PII retention
      return res.status(200).json({
        success: true,
        mode: 'demo',
        request_id,
        created_at,
        message: 'Demo recorded in this browser. Nothing was sent to the CRM.',
        notice: 'Demo mode: not connected to the CRM. This is an academic student prototype.',
        payload_preview: {
          scenario_id: payload.scenario_id,
          name: payload.name,
          email: payload.email,
          buyer_type: payload.buyer_type,
          is_test: payload.is_test
        }
      });
    }

    // Forward to verified Apps Script endpoint
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000);

    try {
      const response = await fetch(appsScriptUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Enquiry-Secret': enquirySecret
        },
        body: JSON.stringify({
          secret: enquirySecret,
          ...payload
        }),
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`Upstream returned HTTP ${response.status}`);
      }

      const result = await response.json().catch(() => null);

      // Verify that receiver acknowledged receipt with matching request_id
      if (!result || (result.status !== 'accepted' && result.success !== true)) {
        return res.status(502).json({
          success: false,
          error: 'Receiver Unacknowledged',
          message: 'We could not confirm receipt. Your details are still in this form. Please try again.'
        });
      }

      return res.status(200).json({
        success: true,
        mode: 'connected',
        request_id,
        created_at,
        message: 'Your project enquiry has been received by the enquiry system. This is not an official TAPMI application.'
      });
    } catch (upstreamErr) {
      clearTimeout(timeoutId);
      return res.status(502).json({
        success: false,
        error: 'Upstream Delivery Failure',
        message: 'We could not confirm receipt. Your details are still in this form. Please try again.',
        details: upstreamErr.name === 'AbortError' ? 'Connection timed out' : 'Upstream communication error'
      });
    }
  } catch (err) {
    return res.status(400).json({
      success: false,
      error: 'Malformed Request',
      message: 'Invalid request data. Please check your entries and try again.'
    });
  }
};
